<?php
 namespace QQWorld\Paypal\Test\Unit\Block\Adminhtml\System\Config; use QQWorld\Backend\Block\Template\Context; use QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager; use QQWorld\Paypal\Block\Adminhtml\System\Config\ResolutionRules; use QQWorld\Paypal\Model\Config\Rules\Reader; class ResolutionRulesTest extends \PHPUnit\Framework\TestCase { protected $resolutionRules; protected $context; protected $readerMock; protected function setUp() { $objectManager = new ObjectManager($this); $this->context = $objectManager->getObject(Context::class); $this->readerMock = $this->getMockBuilder(Reader::class) ->disableOriginalConstructor() ->getMock(); $this->resolutionRules = new ResolutionRules( $this->context, $this->readerMock ); } public function testGetJson($incoming, $outgoing) { $this->readerMock->expects($this->once()) ->method('read') ->willReturn($incoming); $this->assertEquals( $outgoing, $this->resolutionRules->getJson() ); } public function getJsonDataProvider() { return [ [['test' => 'test-value'], '{"test":"test-value"}'], [[], '{}'] ]; } } 